import type { SeedMission, SeedQuestion } from "./content";
import type { TopicKey } from "../../src/lib/topics";

type QuestionDraft = readonly [prompt: string, answer: string, wrong: readonly [string, string, string], hint: string, explanation: string];

type MissionDraft = {
  grade: number;
  subject: "ipa" | "bahasa-indonesia" | "bahasa-inggris";
  order: number;
  title: string;
  topic: string;
  topicKey: TopicKey;
  summary: string;
  questions: readonly QuestionDraft[];
};

function buildMission(draft: MissionDraft): SeedMission {
  const questions: SeedQuestion[] = draft.questions.map(([prompt, answer, wrong, hint, explanation], index) => {
    const answerIndex = (index + draft.order) % 4;
    const options = [...wrong];
    options.splice(answerIndex, 0, answer);
    return {
      type: "multiple_choice",
      prompt,
      options,
      answer,
      hint,
      explanation,
      difficulty: index < 3 ? "mudah" : index < 7 ? "sedang" : "tantangan",
    };
  });
  const slug = `${draft.subject}-${draft.grade}-${draft.order}`;

  return {
    slug,
    title: draft.title,
    description: draft.summary,
    story: `${draft.summary} Selesaikan tantangan secara berurutan, baca setiap petunjuk, dan gunakan pengetahuan yang sesuai dengan materi kelas ${draft.grade}.`,
    learningObjectives: [
      `Memahami konsep ${draft.title.toLowerCase()} sesuai tingkat kelas ${draft.grade}`,
      "Menemukan informasi penting dari contoh dan pertanyaan",
      "Menjelaskan alasan memilih jawaban dengan tepat",
    ],
    orderIndex: draft.order,
    audience: "public",
    gradeLevel: draft.grade,
    subject: draft.subject,
    topic: draft.topic,
    questionTopics: questions.map(() => draft.topicKey),
    questions,
  };
}

